node -e '
const {readFileSync} = require("fs");
const {join} = require("path");
const YAML = require(join(process.cwd(), "node_modules/yaml")).default;
const agentsDir = join(process.cwd(), "..", ".opencode/agents");
const results = {};
for (const agent of ["adv-tron", "adv-verifier", "adv"]) {
  const lines = readFileSync(join(agentsDir, agent+".md"), "utf8").split("\n");
  const end = lines.indexOf("---", 1);
  const doc = YAML.parse(lines.slice(1, end).join("\n"));
  const tools = doc.tools || {};
  const granted = Object.keys(tools).filter(k => k.startsWith("adv_") && k !== "adv_*" && tools[k] === true);
  results[agent] = { granted: granted.length, hasWildcard: tools["adv_*"]===false, seesAdvSpec: !!tools.adv_spec };
}
const pass = results["adv-tron"].granted===11 && !results["adv-tron"].seesAdvSpec && results["adv-verifier"].granted===11 && results["adv"].granted===18;
console.log(JSON.stringify(results));
if (!pass) { process.exit(1); }
console.log("PASS: adv-tron=11, adv-verifier=11, adv=18, adv_spec absent");'
